package com.catpuzzle.assistant; import android.app.Service;import android.content.*;import android.graphics.*;import android.graphics.drawable.GradientDrawable;import android.os.*;import android.view.*;import android.widget.*;import java.util.concurrent.*; public class OverlayService extends Service{WindowManager wm;LinearLayout bar;Draw draw;TextView label;WindowManager.LayoutParams lp,dlp;Handler main=new Handler(Looper.getMainLooper());ExecutorService work=Executors.newSingleThreadExecutor();boolean auto=false,marks=true,busy=false;int speed=1;int[] delay={1100,650,330};String[] sn={"спокойно","обычно","быстро"};BoardAnalyzer.Board board;PuzzleSolver.Move move;int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}GradientDrawable bg(int c){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(22));return d;}TextView cell(String s,int w){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setGravity(17);v.setTextSize(17);v.setBackground(bg(Color.rgb(18,61,47)));v.setLayoutParams(new LinearLayout.LayoutParams(dp(w),dp(43)));return v;}public void onCreate(){super.onCreate();wm=(WindowManager)getSystemService(WINDOW_SERVICE);draw=new Draw(this);dlp=new WindowManager.LayoutParams(-1,-1,Build.VERSION.SDK_INT>=26?2038:2002,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_NOT_TOUCHABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);wm.addView(draw,dlp);bar=new LinearLayout(this);bar.setPadding(dp(4),dp(4),dp(4),dp(4));bar.setBackground(bg(Color.argb(235,10,35,27)));TextView play=cell("▶",48),one=cell("1",42),x=cell("×",42);label=cell("готов",120);label.setTextSize(11);bar.addView(play);bar.addView(one);bar.addView(x);bar.addView(label);lp=new WindowManager.LayoutParams(-2,-2,Build.VERSION.SDK_INT>=26?2038:2002,WindowManager.LayoutParams.FLAG_NOT_FOCUSABLE|WindowManager.LayoutParams.FLAG_LAYOUT_IN_SCREEN,PixelFormat.TRANSLUCENT);lp.gravity=Gravity.TOP|Gravity.START;lp.x=dp(8);lp.y=dp(90);wm.addView(bar,lp);play.setOnClickListener(v->{auto=!auto;play.setText(auto?"■":"▶");label.setText(auto?"авто · "+sn[speed]:"стоп");if(auto)sched(50);});play.setOnLongClickListener(v->{speed=(speed+1)%3;label.setText(sn[speed]);Toast.makeText(this,"Скорость: "+sn[speed],0).show();return true;});one.setOnClickListener(v->step(false));x.setOnClickListener(v->{marks=!marks;x.setAlpha(marks?1f:.45f);draw.invalidate();});final float[] d={0,0};final int[] st={0,0};bar.setOnTouchListener((v,e)->{if(e.getAction()==0){d[0]=e.getRawX();d[1]=e.getRawY();st[0]=lp.x;st[1]=lp.y;}else if(e.getAction()==2&&(Math.abs(e.getRawX()-d[0])>dp(8)||Math.abs(e.getRawY()-d[1])>dp(8))){lp.x=st[0]+(int)(e.getRawX()-d[0]);lp.y=st[1]+(int)(e.getRawY()-d[1]);wm.updateViewLayout(bar,lp);return true;}return false;});}void sched(long d){main.postDelayed(()->{if(auto)step(true);},d);}void step(boolean a){if(busy){if(a)sched(180);return;}if(FrameStore.copy()==null){label.setText("нет захвата");auto=false;return;}busy=true;label.setText("думаю…");bar.setVisibility(View.INVISIBLE);draw.setVisibility(View.INVISIBLE);main.postDelayed(()->{Bitmap shot=FrameStore.copy();bar.setVisibility(View.VISIBLE);draw.setVisibility(View.VISIBLE);if(shot==null){busy=false;return;}work.submit(()->{BoardAnalyzer.Board b=null;PuzzleSolver.Move m;try{b=BoardAnalyzer.analyze(shot);m=PuzzleSolver.next(b);}catch(Throwable t){m=new PuzzleSolver.Move(PuzzleSolver.Kind.NONE,-1,-1,"ошибка анализа");}shot.recycle();BoardAnalyzer.Board fb=b;PuzzleSolver.Move fm=m;main.post(()->apply(fb,fm,a));});},260);}void apply(BoardAnalyzer.Board b,PuzzleSolver.Move m,boolean a){busy=false;board=b;move=m;draw.invalidate();if(m.kind==PuzzleSolver.Kind.NONE){label.setText(m.why.length()>18?m.why.substring(0,18)+"…":m.why);if(a){auto=false;((TextView)bar.getChildAt(0)).setText("▶");}return;}label.setText((m.kind==PuzzleSolver.Kind.CAT?"CAT ":"× ")+(m.r+1)+":"+(m.c+1));if(TapAccessibilityService.instance!=null&&b!=null){TapAccessibilityService.tap(b.cx(m.c),b.cy(m.r),m.kind==PuzzleSolver.Kind.CAT?2:1,90);if(a)sched(delay[speed]);}else if(a){auto=false;((TextView)bar.getChildAt(0)).setText("▶");}}public void onDestroy(){auto=false;work.shutdownNow();if(bar!=null)wm.removeView(bar);if(draw!=null)wm.removeView(draw);super.onDestroy();}public android.os.IBinder onBind(Intent i){return null;}class Draw extends View{Paint p=new Paint(3);Draw(Context c){super(c);}protected void onDraw(Canvas c){if(!marks||board==null||move==null||move.kind==PuzzleSolver.Kind.NONE)return;float cs=board.size/(float)board.n,x=board.left+move.c*cs,y=board.top+move.r*cs;p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(Math.max(4,cs*.07f));if(move.kind==PuzzleSolver.Kind.CROSS){p.setColor(Color.argb(220,255,255,255));float m=cs*.28f;c.drawLine(x+m,y+m,x+cs-m,y+cs-m,p);c.drawLine(x+cs-m,y+m,x+m,y+cs-m,p);}else{p.setColor(Color.argb(230,20,120,75));c.drawCircle(x+cs/2,y+cs/2,cs*.28f,p);}}}}